const stat = (i, l, v) => `<div class="n stat c3"><div class="ico">${ic(i)}</div><div><small>${l}</small><div class="big">${v}</div></div></div>`;
const ring = (p, l) => `<svg viewBox="0 0 120 120" class="ring"><circle cx="60" cy="60" r="50" class="rb0"/><circle cx="60" cy="60" r="50" class="rb1" stroke-dasharray="${3.1416 * p} 999" transform="rotate(-90 60 60)"/><text x="60" y="67" text-anchor="middle">${p}%</text></svg><small>${l}</small>`;
