const bookingsViewBase=V.res; V.res=arg=>{bookingsViewBase(arg);const sel=document.createElement('select');sel.id='fp';sel.setAttribute('aria-label','Payment status');sel.innerHTML='<option value="">All payment statuses</option><option value="unpaid">Unpaid</option><option value="paid">Paid</option>';sel.onchange=loadRes;$('#fs').after(sel);$('#fs').parentElement.classList.add('booking-filters')};
