V.scan = () => { QR_BUSY = false; M().innerHTML = `<div class="n pad c6"><h2>Scan reservation QR</h2><p class="mut">Scan the guest QR or enter its code. Confirm check-in/check-out in the popup.</p><div id="reader"></div><div class="row"><input id="mc" placeholder="Or type the QR code manually"><button class="btn" onclick="lookup($('#mc').value)">Verify code</button></div></div><div class="n pad c6"><h2>Result</h2><div id="sr"><p class="mut">Waiting for a scan...</p></div></div>`; if (window.Html5Qrcode) { sc = new Html5Qrcode('reader'); sc.start({ facingMode: 'environment' }, { fps: 10, qrbox: 220 }, t => lookup(t), () => { }).catch(() => { $('#reader').innerHTML = '<p class="mut">Camera unavailable (needs HTTPS or localhost + permission). Use manual entry.</p>' }) } };
function playCheckoutAlarm() { try { const Ctx=window.AudioContext||window.webkitAudioContext;if(!Ctx)return;const ctx=new Ctx();[0,.22,.44].forEach(delay=>{const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=880;gain.gain.setValueAtTime(.001,ctx.currentTime+delay);gain.gain.exponentialRampToValueAtTime(.16,ctx.currentTime+delay+.025);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+delay+.15);osc.connect(gain);gain.connect(ctx.destination);osc.start(ctx.currentTime+delay);osc.stop(ctx.currentTime+delay+.16)});setTimeout(()=>ctx.close(),900)}catch(e){} }
async function lookup(c) { if (QR_BUSY) return; const code = (c || '').trim(); if (!code) return toast('Scan a QR or enter its code.', 1); QR_BUSY = true; if (sc) sc.stop().catch(() => { }); try { const r = await api('scan', { code }), action = r.next_action, checkoutBlocked = action == 'Check-Out' && +r.remaining_balance > .005, overdue = action == 'Check-Out' && !!r.checkout_overdue, title = action == 'Check-In' ? 'Confirm check-in' : 'Confirm check-out', alert = overdue ? `<div class="checkout-alert" role="alert"><b>⚠ CHECKOUT OVERDUE</b><span>Scheduled checkout was ${esc(r.checkout_due_at)}. Please attend to this guest now.</span></div>` : '', balance = action == 'Check-Out' ? `<p>Total: <b>${money(r.total)}</b> · Paid: <b>${money(r.amount_paid)}</b> · Balance: <b>${money(r.remaining_balance)}</b></p>` : '', blocked = checkoutBlocked ? `<div class="checkout-alert" role="alert"><b>Checkout blocked</b><span>Full payment must be received and approved before checkout. Remaining balance: ${money(r.remaining_balance)}.</span></div>` : '', m = modal(`<h3>${title}?</h3>${alert}<p><b>${esc(r.full_name)}</b></p><p>${esc(r.room_name)} - ${r.guest_count} guests</p><p>${r.check_in_date} &rarr; ${r.check_out_date}</p><span class="badge ${r.status}">${r.status}</span>${balance}${blocked}<div class="row"><button class="btn" id="qrok" ${checkoutBlocked?'disabled':''}>${checkoutBlocked?'Payment required':'Confirm '+action}</button><button class="btn ghost" id="qrcancel">Cancel</button></div>`), box = m.querySelector('.mbox'), close = box.lastElementChild; if(overdue)playCheckoutAlarm(); close.onclick = () => { m.remove(); go('scan') }; m.querySelector('#qrcancel').onclick = () => { m.remove(); go('scan') }; if(!checkoutBlocked)m.querySelector('#qrok').onclick = () => confirmQr(code, m, action) } catch (e) { QR_BUSY = false; $('#sr').innerHTML = `<span class="badge Cancelled">${esc(e.message)}</span><button class="btn sm ghost" onclick="go('scan')">Scan another</button>` } }
async function confirmQr(code, m, action) { const b = m.querySelector('#qrok'); b.disabled = true; b.textContent = 'Processing...'; try { const r = await api('checkqr', { code }); m.remove(); QR_BUSY = false; const next = r.status == 'Checked-In', msg = next ? 'Check-in complete. The guest keeps using the same QR at checkout.' : 'Check-out complete. This QR has now been deactivated.'; $('#sr').innerHTML = `<div class="card"><h3>${esc(r.full_name)}</h3><span>${esc(r.room_name)} - ${r.guest_count} guests</span><span>${r.check_in_date} &rarr; ${r.check_out_date}</span><span class="badge ${r.status}">${r.status}</span><small>${msg}</small><button class="btn sm ghost" onclick="go('scan')">Scan next guest</button></div>` } catch (e) { m.remove(); QR_BUSY = false; $('#sr').innerHTML = `<span class="badge Cancelled">${esc(e.message)}</span>` } }

const roomCards = () => ROOMS.map(r => `<div class="n card c4">${rimg(r)}<h3>${esc(r.room_name)}</h3><small>${esc(r.category)} - ${r.capacity} pax</small><b>${money(r.rate_per_night)}/night</b><span class="badge ${r.is_available == 1 ? 'Confirmed' : 'Cancelled'}">${r.is_available == 1 ? 'Open' : 'Closed'}</span><div class="row"><button class="btn sm" onclick="roomForm(${r.room_id})">Edit</button><button class="btn sm ghost" onclick="archiveRoom(${r.room_id},${ROOM_ARCH ? 0 : 1})">${ROOM_ARCH ? 'Restore' : 'Archive'}</button><button class="btn sm bad" onclick="deleteRoom(${r.room_id})">Delete</button></div></div>`).join('') || '<p class="mut">No rooms here.</p>';
async function refreshRooms() { ROOMS = await api('rooms', null, '&arch=' + ROOM_ARCH); if ($('#roomcards')) $('#roomcards').innerHTML = roomCards(); if ($('#cal') && !ROOM_ARCH) await cal() }
V.rooms = async () => { ROOM_ARCH = 0; ROOMS = await api('rooms'); M().innerHTML = `<div class="c12 row" style="margin:0"><h2>Rooms & accommodations</h2><button class="btn sm ${ROOM_ARCH ? 'ghost' : ''}" onclick="toggleRoomArchive()">Active rooms</button><button class="btn sm ${ROOM_ARCH ? '' : 'ghost'}" onclick="toggleRoomArchive(1)">Archived rooms</button><div class="grow"></div>${!ROOM_ARCH ? '<button class="btn" onclick="roomForm(0)">+ Add room</button>' : ''}</div><div id="roomcards" class="c12 g">${roomCards()}</div>${!ROOM_ARCH ? `<div class="n pad c12"><div class="row calnav"><h2>Availability calendar</h2><button class="btn sm ghost" onclick="shiftCal(-1)">&lsaquo;</button><input type="month" id="cm" value="${today().slice(0, 7)}" onchange="cal()"><button class="btn sm ghost" onclick="shiftCal(1)">&rsaquo;</button></div><div id="cal"></div></div>` : ''}`; if (!ROOM_ARCH) cal() };
