function uploadProfile(inp) { const f = inp.files[0]; if (!f) return; const im = new Image(); im.onload = () => { const s = Math.min(1, 700 / im.width), c = document.createElement('canvas'); c.width = im.width * s; c.height = im.height * s; c.getContext('2d').drawImage(im, 0, 0, c.width, c.height); T(async () => { const r = await api('profilephoto', { photo: c.toDataURL('image/jpeg', .82) }); $('#profileav').innerHTML = `<img src="${esc(r.photo)}" alt="Profile photo">`; toast('Profile photo uploaded') }) }; im.src = URL.createObjectURL(f) }
