V.users = async () => { const us = await api('users'); M().innerHTML = `<div class="n pad c12"><h2>Add staff / admin</h2><div class="row"><input id="un" placeholder="Full name"><input id="ue" placeholder="Email"><input id="up" type="password" placeholder="Password (6+)"><select id="ur"><option>Staff</option><option>Admin</option></select><button class="btn" onclick="addU()">Add</button></div></div><div class="n pad c12"><h2>All users</h2><div class="tw"><table><tr><th>Name</th><th>Email</th><th>Role</th><th></th></tr><tbody id="userrows">${userRows(us)}</tbody></table></div></div>` };
