V.mine = async () => { const rs = keep(await api('mine')); M().innerHTML = `<div class="n pad c12"><div class="row"><h2>My bookings</h2><div class="grow"></div><small>Booking totals and payment status</small></div><div class="tw">${rs.length ? `<table class="booking-table"><colgroup><col style="width:8%"><col style="width:17%"><col style="width:21%"><col style="width:8%"><col style="width:12%"><col style="width:12%"><col style="width:11%"><col style="width:23%"></colgroup><thead><tr><th>Booking ID</th><th>Room / cottage</th><th>Check-in / check-out</th><th>Guests</th><th>Total</th><th>Payment</th><th>Booking</th><th>Actions</th></tr></thead><tbody>${rs.map(r => `<tr><td>#${r.reservation_id}</td><td>${esc(r.room_name)}</td><td>${r.check_in_date}<br><small>to ${r.check_out_date}</small></td><td>${r.guest_count}</td><td>${money(r.nights * r.rate_per_night)}</td><td><span class="badge ${r.payment_status}">${r.payment_status}</span><br><small>${money(r.amount_paid || 0)} paid</small></td><td><span class="badge ${r.status}">${r.status}</span></td><td class="booking-actions"><button class="btn sm ghost" onclick="reservationInfo(${r.reservation_id})">View details</button><button class="btn sm ghost" onclick="receipt(${r.reservation_id})">Receipt & QR</button>${['Pending', 'Confirmed'].includes(r.status) && r.payment_status == 'Unpaid' ? `<button class="btn sm bad" onclick="cancelR(${r.reservation_id})">Cancel booking</button>` : ''}</td></tr>`).join('')}</tbody></table>` : '<p class="mut">No bookings yet.</p>'}</div></div>` };
const searchBeforeFavorites = search; search = async () => { await searchBeforeFavorites(); const ci = $('#ci')?.value, co = $('#co')?.value; if (!ci || !co || !$('#rl')) return; try { const rooms = await api('avail', null, `&ci=${ci}&co=${co}`); $('#rl').querySelectorAll('.card').forEach((card, i) => { const r = rooms[i]; if (!r) return; const b = document.createElement('button'); b.className = 'btn sm ghost favorite-toggle'; b.id = 'fav-' + r.room_id; b.textContent = r.is_favorite ? '♥ Saved' : '♡ Save favorite'; b.onclick = () => toggleFavorite(r.room_id); card.append(b) }) } catch (e) { } };
