V.payments = async () => { const d = await api('payments'), due = d.bookings.reduce((a, r) => a + Math.max(0, +r.total - (+r.amount_paid || 0)), 0), paid = d.bookings.reduce((a, r) => a + (+r.amount_paid || 0), 0); M().innerHTML = `<div class="n stat c6"><div class="ico">${ic('card')}</div><div><small>Amount paid</small><div class="big">${money(paid)}</div></div></div><div class="n stat c6"><div class="ico">${ic('clock')}</div><div><small>Remaining balance</small><div class="big">${money(due)}</div></div></div><div class="n pad c12"><h2>Unpaid and partially paid bookings</h2><div class="tw">${d.bookings.filter(r => r.payment_status != 'Paid').map(r => `<div class="paymentrow"><b>#${r.reservation_id} · ${esc(r.room_name)}</b><span>${r.check_in_date} to ${r.check_out_date}</span><span>${money(r.amount_paid)} paid of ${money(r.total)} · ${r.payment_status}</span><button class="btn sm ghost" onclick="paymentReceipt(${r.reservation_id})">Print statement</button></div>`).join('') || '<p class="mut">All bookings are paid in full.</p>'}</div></div><div class="n pad c12"><h2>Payment history</h2><div class="tw">${d.history.length ? `<table class="payment-table"><thead><tr><th>Date</th><th>Booking</th><th>Room</th><th>Method</th><th>Amount</th><th></th></tr></thead><tbody>${d.history.map(p => `<tr><td>${p.paid_at.slice(0, 16)}</td><td>#${p.reservation_id}</td><td>${esc(p.room_name)}</td><td>${esc(p.payment_method)}</td><td>${money(p.amount)}</td><td><button class="btn sm ghost" onclick="paymentReceipt(${p.reservation_id})">Print</button></td></tr>`).join('')}</tbody></table>` : '<p class="mut">No payments recorded yet. Payments are recorded by resort staff.</p>'}</div></div>` };
async function paymentReceipt(id) { const d = await api('payments'), r = d.bookings.find(x => x.reservation_id == id), ps = d.history.filter(x => x.reservation_id == id); if (!r) return; modal(`<div class="logo">MNB<span>Resort</span></div><h3>Payment statement · #${id}</h3><p>${esc(r.room_name)} · ${r.check_in_date} to ${r.check_out_date}</p><p>Total: <b>${money(r.total)}</b> · Paid: <b>${money(r.amount_paid)}</b> · Balance: <b>${money(Math.max(0, r.total - r.amount_paid))}</b></p><div class="tw"><table class="payment-table"><thead><tr><th>Date</th><th>Method</th><th>Amount</th></tr></thead><tbody>${ps.map(p => `<tr><td>${p.paid_at.slice(0, 16)}</td><td>${esc(p.payment_method)}</td><td>${money(p.amount)}</td></tr>`).join('') || '<tr><td colspan="3">No payments recorded</td></tr>'}</tbody></table></div><button class="btn" onclick="print()">Print / Save PDF</button>`) }
V.reviews = async () => { const d = await api('reviews'); M().innerHTML = `<div class="n pad c12"><h2>Reviews & ratings</h2><p class="mut">You can review a stay after it is completed.</p></div>${d.eligible.length ? `<div class="n pad c12"><h2>Write a review</h2><div class="row"><label>Completed booking<select id="rvbooking">${d.eligible.map(r => `<option value="${r.reservation_id}">#${r.reservation_id} · ${esc(r.room_name)} · ${r.check_out_date}</option>`).join('')}</select></label><label>Rating<select id="rvrating"><option value="5">★★★★★ · Excellent</option><option value="4">★★★★☆ · Good</option><option value="3">★★★☆☆ · Okay</option><option value="2">★★☆☆☆ · Poor</option><option value="1">★☆☆☆☆ · Bad</option></select></label></div><textarea id="rvtext" maxlength="1000" placeholder="Share your stay experience"></textarea><button class="btn" onclick="submitReview()">Post review</button></div>` : ''}<div class="n pad c12"><h2>Guest reviews</h2>${d.reviews.map(r => `<article class="review"><b>${esc(r.room_name)}</b><span class="stars">${'★'.repeat(r.rating)}${'☆'.repeat(5 - r.rating)}</span><p>${esc(r.review_text)}</p><small>${esc(r.full_name)} · ${r.created_at.slice(0, 10)}</small></article>`).join('') || '<p class="mut">No reviews yet.</p>'}</div>` };
async function submitReview() { await T(async () => { await api('submitreview', { reservation_id: $('#rvbooking').value, rating: $('#rvrating').value, review: $('#rvtext').value }); toast('Thanks for sharing your review!'); go('reviews') }) }
V.notifications = async () => { const ns = await api('notifications'); await api('readnotifications'); NN = 0; $('#nb').innerHTML = ic('bell'); M().innerHTML = `<div class="n pad c12"><h2>Notifications</h2>${U.user_role != 'Guest' ? `<div class="announceform"><h3>Resort announcement</h3><div class="row"><input id="antitle" maxlength="120" placeholder="Announcement title"><input id="anbody" maxlength="500" placeholder="Message for all guests"><button class="btn" onclick="sendAnnouncement()">Send to guests</button></div></div>` : ''}${ns.map(n => `<article class="notification ${n.is_read ? '' : 'unread'}"><span class="badge">${esc(n.notification_type)}</span><div><b>${esc(n.title)}</b><p>${esc(n.message)}</p><small>${n.created_at.slice(0, 16)}</small></div>${n.reservation_id ? `<button class="btn sm ghost" onclick="go('mine')">View booking</button>` : ''}</article>`).join('') || '<p class="mut">You are all caught up.</p>'}</div>` };
async function sendAnnouncement() { await T(async () => { const r = await api('announce', { title: $('#antitle').value, message: $('#anbody').value }); toast(`Announcement sent to ${r.count} guests`); go('notifications') }) }
V.info = () => { M().innerHTML = `<div class="n hero c12"><h1>Welcome to MNB Resort</h1><p class="mut">Papaya, Nasugbu, Batangas</p><p>A relaxed coastal stay for families, couples, and groups.</p></div><div class="n pad c6"><h2>Amenities</h2><ul><li>Beach access and swimming</li><li>Guest rooms, family suites, cottages, and event space</li><li>Resort staff assistance during your stay</li></ul></div><div class="n pad c6"><h2>Guest guidelines</h2><ul><li>Bring your booking receipt and QR code for check-in.</li><li>Follow staff instructions and keep shared areas tidy.</li><li>Confirm special requests with resort staff before arrival.</li></ul></div><div class="n pad c6"><h2>Check-in & check-out</h2><p>Check-in and check-out dates are shown on your booking. Please coordinate your arrival time with the resort through Messages.</p></div><div class="n pad c6"><h2>Contact & location</h2><p>Papaya, Nasugbu, Batangas</p><button class="btn sm" onclick="go('msg')">Contact resort</button> <a class="btn sm ghost" target="_blank" rel="noopener" href="https://maps.google.com/?q=MNB+Resort+Papaya+Nasugbu+Batangas">Open map</a></div><div class="n pad c12"><h2>Frequently asked questions</h2><details><summary>How do I know my booking is confirmed?</summary><p>Check My Bookings and Notifications. Staff confirmation also sends a notification.</p></details><details><summary>Where is my QR code?</summary><p>Open Receipt & QR from My Bookings after your stay is confirmed.</p></details><details><summary>How do I pay?</summary><p>Contact resort staff. They record payments and the updated balance appears in Payments.</p></details><details><summary>Can I cancel a booking?</summary><p>Pending or confirmed unpaid bookings can be cancelled from My Bookings. Contact the resort for paid bookings.</p></details></div>` };
const profileView = V.profile; V.profile = async () => { const p = await api('myprofile'); M().innerHTML = `<div class="n pad c4 profilecard"><div class="av big profileav" id="profileav">${p.photo ? `<img src="${esc(p.photo)}" alt="Profile photo">` : esc(p.full_name[0])}</div><label class="uploadbtn">Upload profile photo<input id="profilefile" type="file" accept="image/*" onchange="uploadProfile(this)"></label><h2>${esc(p.full_name)}</h2><small>${p.user_role} · member since ${p.created_at.slice(0, 10)}</small><button class="btn ghost" onclick="logout()">Log out</button></div><div class="n pad c8"><h2>Edit profile</h2><div class="row"><label>Full name<input id="pn" value="${esc(p.full_name)}"></label><label>Phone<input id="pph" value="${esc(p.phone)}"></label><label>Email<input id="pe" value="${esc(p.email)}"></label><label>Address<input id="pa" value="${esc(p.address || '')}" maxlength="255"></label><label>Date of birth (optional)<input id="pdob" type="date" value="${esc(p.date_of_birth || '')}"></label></div><button class="btn" onclick="saveP()">Save changes</button></div><div class="n pad c12"><h2>Change password</h2><div class="row"><label>Current<input id="o1" type="password"></label><label>New (6+)<input id="o2" type="password"></label><label>Confirm new<input id="o3" type="password"></label></div><button class="btn" onclick="savePw()">Update password</button></div>` };
saveP = async () => { await T(async () => { const r = await api('profile', { name: $('#pn').value, phone: $('#pph').value, email: $('#pe').value, address: $('#pa').value, dob: $('#pdob').value || null }); U = r.user; $('#who').textContent = U.full_name + ' · ' + U.user_role; toast('Profile updated'); go('profile') }) };
const detailBase = reservationInfo; reservationInfo = id => { detailBase(id); const box = document.querySelector('.modal .mbox'), r = RS[id]; if (!box || !r) return; box.insertAdjacentHTML('beforeend', `<p class="payment-detail">Payment: <b>${esc(r.payment_status || 'Unpaid')}</b> · ${money(r.amount_paid || 0)} paid</p>${U.user_role != 'Guest' && r.status === 'Checked-In' && r.payment_status !== 'Paid' ? `<button class="btn sm" onclick="recordPaymentForm(${id})">Record payment</button>` : ''}`) };
function recordPaymentForm(id) { const r = RS[id]; if (!r || r.status !== 'Checked-In' || r.payment_status === 'Paid') return toast('Payment is available only for checked-in bookings with a balance.', 1); document.querySelectorAll('.modal').forEach(m => m.remove()); const total = r.nights * r.rate_per_night, remaining = Math.max(0, total - (+r.amount_paid || 0)), canUnpay = !(+r.amount_paid); modal(`<h3>Record payment · Booking #${id}</h3><p>Total: <b>${money(total)}</b> · Previously paid: <b>${money(r.amount_paid || 0)}</b></p><label>Payment status<select id="paystatus" onchange="paymentAmountMode(${remaining})"><option value="Paid" ${remaining<=0?'selected':''} ${remaining<=0?'disabled':''}>Paid</option><option value="Unpaid" ${remaining>0?'selected':''} ${canUnpay?'':'disabled'}>Unpaid</option></select></label><label>Amount received<input id="payamount" type="number" min="${remaining>0?'0.01':'0'}" max="${remaining}" step="0.01" value="${remaining.toFixed(2)}" ${remaining>0?'disabled':''}></label><label>Payment method<select id="paymethod"><option>Cash</option><option>Bank transfer</option><option>GCash</option><option>Card</option><option>Other</option></select></label><small id="payhint" class="mut">Choose Paid and enter the full remaining balance, or keep Unpaid.</small><button class="btn" onclick="recordPayment(${id})" ${remaining<=0&&!canUnpay?'disabled':''}>Save payment status</button>`) }
function paymentAmountMode(remaining){const paid=$('#paystatus').value==='Paid';$('#payamount').disabled=!paid;$('#payamount').min=paid?'0.01':'0';$('#payamount').value=paid?remaining.toFixed(2):'0';$('#payhint').textContent=paid?'Enter the full remaining balance. The receipt will show the payment and updated balance.':'Unpaid bookings stay at ₱0 paid.'}
async function recordPayment(id) { await T(async () => { await api('recordpayment', { reservation_id: id, amount: $('#payamount').value, method: $('#paymethod').value, payment_status: $('#paystatus').value }); document.querySelector('.modal')?.remove(); toast('Payment status saved and receipt updated'); await loadRes(); if(CUR!=='res')go(CUR) }) }
/* ---------- admin workspace ---------- */
async function adminDashboard() {
    const d = await api('adminsummary'), all = await api('list');
    const pending = all.filter(r => r.status == 'Pending');
    const overdue = all.filter(r => r.checkout_overdue);
    const due = all.filter(r => ['Pending', 'Confirmed', 'Checked-In'].includes(r.status) && r.payment_status != 'Paid');
    const events = d.recent.map(x => `<div class="activityrow"><b>${esc(x.action)}</b><span>${esc(x.details)}</span><small>${esc(x.full_name || 'Admin')} · ${x.created_at.slice(0, 16)}</small></div>`).join('');
    const hr = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Manila' })).getHours();
    const greet = hr < 12 ? 'Good morning' : hr < 18 ? 'Good afternoon' : 'Good evening';
    const occupancy = d.rooms ? Math.round(d.occupied / d.rooms * 100) : 0;
    const metric = (icon, title, value, note, featured = false) => `<div class="n stat c3 dashboard-kpi ${featured ? 'featured' : ''}"><div class="ico">${ic(icon)}</div><div><small>${title}</small><div class="big">${value}</div><small>${note}</small></div></div>`;
    M().innerHTML = `<div class="n hero c12 dashboard-welcome"><div class="dashboard-welcome-copy"><span class="dashboard-eyebrow">RESORT OVERVIEW</span><h1>${greet}, ${esc(U.full_name.split(' ')[0])}</h1><p class="mut">Key activity and performance at a glance.</p></div><div class="dashboard-welcome-side"><span class="dashboard-mascot" role="img" aria-label="Tropical resort turtle mascot">🐢</span><div class="dashboard-links"><button class="btn sm ghost" onclick="go('res')">Bookings</button><button class="btn sm ghost" onclick="go('rooms')">Inventory</button></div></div></div>
        ${overdue.length ? `<div class="n checkout-alert c12" role="alert"><b>⚠ ${overdue.length} CHECKOUT${overdue.length === 1 ? '' : 'S'} OVERDUE</b><span>${overdue.slice(0,3).map(r=>`#${r.reservation_id} · ${esc(r.full_name)} · ${esc(r.room_name)}`).join('  |  ')}${overdue.length>3?'  |  + more':''}</span><button class="btn sm ghost" onclick="go('res',{status:'Checked-In'})">Review check-ins</button></div>` : ''}
        ${metric('ticket', 'Total bookings', d.bookings, 'All recorded stays', true)}
        ${metric('card', 'Revenue received', money(d.revenue), 'Approved payments', true)}
        ${metric('clock', 'Awaiting approval', d.pending, 'Pending bookings')}
        ${metric('bed', 'Room occupancy', `${occupancy}%`, `${d.occupied} of ${d.rooms} rooms in use`)}
        ${metric('list', "Today's arrivals", d.today, 'Bookings checking in today')}
        ${metric('card', 'Payment proofs', d.pending_payments, 'Waiting for review')}
        <div class="n pad c7 dashboard-panel"><div class="section-heading"><div><span class="dashboard-eyebrow">NEXT 7 DAYS</span><h2>Upcoming check-ins</h2></div><button class="btn sm ghost" onclick="go('res',{status:'Confirmed'})">View bookings</button></div>${d.upcoming.map(r => `<div class="adminlistrow"><b>#${r.reservation_id} · ${esc(r.full_name)}</b><span>${esc(r.room_name)} · ${r.check_in_date}</span></div>`).join('') || '<p class="mut">No check-ins scheduled in the next seven days.</p>'}</div>
        <div class="n pad c5 dashboard-panel"><div class="section-heading"><div><span class="dashboard-eyebrow">LIVE STATUS</span><h2>Room availability</h2></div><button class="btn sm ghost" onclick="go('availability')">Open calendar</button></div><div class="occupancy"><div><small>Available</small><b>${d.available}</b></div><div><small>Occupied</small><b>${d.occupied}</b></div><div><small>Total</small><b>${d.rooms}</b></div></div><div class="occupancy-meter"><i style="width:${occupancy}%"></i></div><p class="mut">${occupancy}% of bookable rooms are occupied.</p></div>
        <div class="n pad c12 dashboard-panel dashboard-bookings"><div class="section-heading"><div><span class="dashboard-eyebrow">NEEDS ATTENTION</span><h2>Pending booking approvals</h2></div><button class="btn sm ghost" onclick="go('res',{status:'Pending'})">All pending</button></div><div class="tw">${resTable(pending.slice(0, 3))}</div></div>
        <div class="n pad c6 dashboard-panel"><div class="section-heading"><div><span class="dashboard-eyebrow">COLLECTION</span><h2>Pending payments</h2></div><button class="btn sm ghost" onclick="go('paymentsAdmin',{filter:'pending'})">Review (${d.payment_proofs})</button></div>${due.slice(0, 4).map(r => `<div class="adminlistrow"><b>#${r.reservation_id} · ${esc(r.full_name)}</b><span>${esc(r.room_name)} · ${r.payment_status} · ${money(Math.max(0, r.nights * r.rate_per_night - (r.amount_paid || 0)))}</span><button class="btn sm ghost" onclick="reservationInfo(${r.reservation_id})">Details</button></div>`).join('') || '<p class="mut">No unpaid bookings.</p>'}</div>
        <div class="n pad c6 dashboard-panel"><div class="section-heading"><div><span class="dashboard-eyebrow">LATEST UPDATES</span><h2>Recent admin activity</h2></div><button class="btn sm ghost" onclick="go('activity')">Activity log</button></div>${events || '<p class="mut">Admin actions will appear here.</p>'}</div>`;
}
V.paymentsAdmin = async (arg) => { const rows = await api('adminpayments'), filter = arg?.filter || 'all', shown = rows.filter(p => filter == 'pending' ? p.transaction_type == 'Payment' && p.status == 'Pending' : filter == 'refunds' ? p.transaction_type == 'Refund' : true); M().innerHTML = `<div class="n pad c12"><div class="row"><h2>Payment management</h2><select id="payfilter" onchange="go('paymentsAdmin',{filter:this.value})"><option value="all" ${filter == 'all' ? 'selected' : ''}>All transactions</option><option value="pending" ${filter == 'pending' ? 'selected' : ''}>Pending proofs</option><option value="refunds" ${filter == 'refunds' ? 'selected' : ''}>Refunds</option></select></div><p class="mut">Staff recorded payments are approved immediately. Guest submitted proofs and refunds require admin review.</p><div class="tw"><table class="admin-table"><thead><tr><th>Transaction</th><th>Customer / booking</th><th>Stay</th><th>Amount</th><th>Method</th><th>Status</th><th>Proof / actions</th></tr></thead><tbody>${shown.map(p => `<tr><td>#${p.payment_id}<br><small>${p.transaction_type}</small></td><td>${esc(p.full_name)}<br><small>Booking #${p.reservation_id}</small></td><td>${p.check_in_date} to ${p.check_out_date}<br><small>${esc(p.room_name)}</small></td><td>${money(p.amount)}</td><td>${esc(p.payment_method)}</td><td><span class="badge ${p.status}">${p.status}</span></td><td class="acts">${p.proof ? `<button class="btn sm ghost" onclick="viewPaymentProof(${p.payment_id})">View proof</button>` : ''}${p.status == 'Pending' ? `<button class="btn sm" onclick="paymentDecision(${p.payment_id},'Approved')">Approve</button><button class="btn sm bad" onclick="paymentDecision(${p.payment_id},'Rejected')">Reject</button>` : ''}${p.transaction_type == 'Payment' && p.status == 'Approved' ? `<button class="btn sm ghost" onclick="refundForm(${p.payment_id},${p.reservation_id},${p.amount})">Refund</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="7">No transactions in this view.</td></tr>'}</tbody></table></div></div>` };
function viewPaymentProof(id) { const p = window.ADMIN_PAYMENTS?.find(x => x.payment_id == id); if (!p) return; modal(`<h3>Payment proof · #${id}</h3>${p.proof ? `<img class="proofimage" src="${esc(p.proof)}" alt="Uploaded payment proof">` : '<p>No proof attached.</p>'}`) }
async function paymentDecision(id, status) { await T(async () => { await api('reviewpayment', { id, status }); auditRefresh('Payment ' + status, `Transaction #${id}`); go('paymentsAdmin', { filter: status == 'Approved' ? 'all' : 'pending' }) }) }
function refundForm(payment_id, reservation_id, amount) { modal(`<h3>Request refund</h3><p>Payment #${payment_id} · Booking #${reservation_id}</p><label>Refund amount<input id="refundamount" type="number" min="0.01" max="${amount}" step="0.01" value="${amount}"></label><button class="btn" onclick="createRefund(${payment_id})">Create pending refund</button>`) }
async function createRefund(payment_id) { await T(async () => { await api('createrefund', { payment_id, amount: $('#refundamount').value }); document.querySelector('.modal')?.remove(); toast('Refund added to admin approval queue'); go('paymentsAdmin', { filter: 'refunds' }) }) }
async function auditRefresh() { }
V.packages = async () => { const rows = await api('packages'); M().innerHTML = `<div class="n pad c12"><div class="row"><h2>Packages & add-ons</h2><div class="grow"></div><button class="btn" onclick="packageForm()">Add item</button></div><div class="g">${rows.map(p => `<article class="n card c4"><span class="badge">${esc(p.item_type)}</span><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><b>${money(p.price)}</b><span class="badge ${p.is_active ? 'Confirmed' : 'Cancelled'}">${p.is_active ? 'Active' : 'Disabled'}</span><div class="row"><button class="btn sm ghost" onclick="packageForm(${p.package_id})">Edit</button><button class="btn sm ${p.is_active ? 'bad' : ''}" onclick="packageActive(${p.package_id},${p.is_active ? 0 : 1})">${p.is_active ? 'Disable' : 'Enable'}</button></div></article>`).join('') || '<p class="mut">No packages or add-ons yet.</p>'}</div></div>`; window.PACKAGES = rows };
function packageForm(id) { const p = (window.PACKAGES || []).find(x => x.package_id == id) || { item_type: 'Package', name: '', description: '', price: 0 }; modal(`<h3>${id ? 'Edit' : 'Add'} package or add-on</h3><label>Type<select id="pktype"><option ${p.item_type == 'Package' ? 'selected' : ''}>Package</option><option ${p.item_type == 'Add-on' ? 'selected' : ''}>Add-on</option></select></label><label>Name<input id="pkname" value="${esc(p.name)}"></label><label>Description<textarea id="pkdesc">${esc(p.description)}</textarea></label><label>Price<input type="number" min="0" step="0.01" id="pkprice" value="${p.price}"></label><button class="btn" onclick="savePackage(${id || 0})">Save</button>`) }
async function savePackage(id) { await T(async () => { await api('savepackage', { id, type: $('#pktype').value, name: $('#pkname').value, description: $('#pkdesc').value, price: $('#pkprice').value }); document.querySelector('.modal')?.remove(); go('packages') }) }
async function packageActive(id, active) { await T(async () => { await api('packageactive', { id, active }); go('packages') }) }
V.reviewsAdmin = async () => { const d = await api('reviews'); M().innerHTML = `<div class="n pad c12"><h2>Reviews & ratings</h2><div class="tw">${d.reviews.map(r => `<article class="review"><b>${esc(r.room_name)}</b><span class="stars">${'★'.repeat(r.rating)}${'☆'.repeat(5 - r.rating)}</span><p>${esc(r.review_text)}</p><small>${esc(r.full_name)} · Booking #${r.reservation_id} · ${r.created_at.slice(0, 10)}</small>${r.admin_reply ? `<p><b>Resort reply:</b> ${esc(r.admin_reply)}</p>` : ''}<div class="row"><button class="btn sm ghost" onclick="replyReview(${r.review_id})">Reply</button><button class="btn sm ${r.is_hidden ? '' : 'bad'}" onclick="reviewAction(${r.review_id},'${r.is_hidden ? 'show' : 'hide'}')">${r.is_hidden ? 'Show review' : 'Hide review'}</button></div></article>`).join('') || '<p class="mut">No reviews to moderate.</p>'}</div></div>` };
function replyReview(id) { modal(`<h3>Reply to review #${id}</h3><textarea id="reviewreply" maxlength="1000" placeholder="Write a response from MNB Resort"></textarea><button class="btn" onclick="reviewAction(${id},'reply')">Post reply</button>`) }
async function reviewAction(id, action) { await T(async () => { await api('reviewaction', { id, action, reply: $('#reviewreply')?.value || '' }); document.querySelector('.modal')?.remove(); go('reviewsAdmin') }) }
V.settings = async () => { const s = await api('settings'); M().innerHTML = `<div class="n pad c12"><h2>Resort settings</h2><p class="mut">These details are shown to guests and used by staff.</p><div class="row settingsgrid"><label>Resort name<input id="set_name" value="${esc(s.resort_name)}"></label><label>Logo image URL<input id="set_logo" value="${esc(s.resort_logo || '')}"></label><label>Contact number<input id="set_phone" value="${esc(s.contact_number)}"></label><label>Contact email<input id="set_email" value="${esc(s.contact_email)}"></label><label>Address<input id="set_address" value="${esc(s.address)}"></label><label>Check-in time<input type="time" id="set_in" value="${esc(s.check_in_time)}"></label><label>Check-out time<input type="time" id="set_out" value="${esc(s.check_out_time)}"></label><label>Payment methods<input id="set_methods" value="${esc(s.payment_methods)}"></label></div><label>Cancellation policy<textarea id="set_cancel">${esc(s.cancellation_policy)}</textarea></label><button class="btn" onclick="saveSettings()">Save settings</button></div>` };
async function saveSettings() { await T(async () => { await api('savesettings', { resort_name: $('#set_name').value, resort_logo: $('#set_logo').value, contact_number: $('#set_phone').value, contact_email: $('#set_email').value, address: $('#set_address').value, check_in_time: $('#set_in').value, check_out_time: $('#set_out').value, payment_methods: $('#set_methods').value, cancellation_policy: $('#set_cancel').value }); toast('Settings saved'); go('settings') }) }
V.activity = async () => { const rows = await api('activity'); M().innerHTML = `<div class="n pad c12"><h2>Admin activity log</h2><div class="tw"><table><thead><tr><th>Date / time</th><th>Admin</th><th>Action</th><th>Details</th></tr></thead><tbody>${rows.map(x => `<tr><td>${x.created_at.slice(0, 16)}</td><td>${esc(x.full_name || 'Deleted admin')}</td><td>${esc(x.action)}</td><td>${esc(x.details)}</td></tr>`).join('') || '<tr><td colspan="4">No admin activities recorded yet.</td></tr>'}</tbody></table></div></div>` };
const oldUsersView = V.users; V.users = async () => { const us = await api('users'), customers = us.filter(x => x.user_role == 'Guest'); M().innerHTML = `<div class="n pad c12"><h2>Add staff / admin</h2><div class="row"><input id="un" placeholder="Full name"><input id="ue" placeholder="Email"><input id="up" type="password" placeholder="Password (6+)"><select id="ur"><option>Staff</option><option>Admin</option></select><button class="btn" onclick="addU()">Add account</button></div></div><div class="n pad c12"><h2>Users & customers</h2><input id="usersearch" placeholder="Search name or email" oninput="filterAdminUsers()"><div class="tw"><table id="admUsers"><thead><tr><th>Customer</th><th>Email / phone</th><th>Bookings</th><th>Completed</th><th>Cancelled</th><th>Total paid</th><th>Account</th><th></th></tr></thead><tbody>${customers.map(u => `<tr data-search="${esc((u.full_name + ' ' + u.email).toLowerCase())}"><td>${esc(u.full_name)}</td><td>${esc(u.email)}<br><small>${esc(u.phone || '')}</small></td><td>${u.bookings}</td><td>${u.completed}</td><td>${u.cancelled}</td><td>${money(u.spent)}</td><td><span class="badge ${u.is_active ? 'Confirmed' : 'Cancelled'}">${u.is_active ? 'Active' : 'Inactive'}</span></td><td class="acts"><button class="btn sm ghost" onclick="customerDetails(${u.user_id})">View profile</button><button class="btn sm ${u.is_active ? 'bad' : ''}" onclick="customerActive(${u.user_id},${u.is_active ? 0 : 1})">${u.is_active ? 'Deactivate' : 'Activate'}</button></td></tr>`).join('') || '<tr><td colspan="8">No customers found.</td></tr>'}</tbody></table></div></div>` };
function filterAdminUsers() { const q = $('#usersearch').value.toLowerCase(); document.querySelectorAll('#admUsers tbody tr').forEach(r => r.style.display = r.dataset.search?.includes(q) ? '' : 'none') }
async function customerDetails(id) { const u = await api('userdetail', null, '&id=' + id); modal(`<h3>${esc(u.full_name)}</h3><p>${esc(u.email)} · ${esc(u.phone || '')}</p><p>${esc(u.address || 'No address on file')}</p><h3>Booking history</h3><div class="tw"><table><thead><tr><th>Booking</th><th>Room</th><th>Stay</th><th>Status</th></tr></thead><tbody>${u.bookings.map(r => `<tr><td>#${r.reservation_id}</td><td>${esc(r.room_name)}</td><td>${r.check_in_date} to ${r.check_out_date}</td><td>${esc(r.status)}</td></tr>`).join('') || '<tr><td colspan="4">No bookings</td></tr>'}</tbody></table></div><h3>Payment history</h3>${u.payments.map(p => `<p>#${p.reservation_id} · ${money(p.amount)} · ${esc(p.payment_method)} · ${p.status}</p>`).join('') || '<p>No payments recorded.</p>'}`) }
async function customerActive(id, active) { await T(async () => { await api('useractive', { id, active }); go('users') }) }
/* Admin reports use payment transactions and booking data for separate chart views. */
const donutChart = rows => { const total = rows.reduce((s, x) => s + (+x[1] || 0), 0), colors = ['#23aaa3', '#6db3b7', '#aac2bf', '#878362', '#504f2f', '#ddd9cc']; let n = 0; const stops = rows.map((x, i) => { const a = n; n += total ? (+x[1] || 0) / total * 100 : 0; return `${colors[i % colors.length]} ${a}% ${n}%` }).join(',') || '#ddd9cc 0% 100%'; return `<div class="donutrow"><div class="donut" style="background:conic-gradient(${stops})"><span>${total}</span></div><div class="donutlegend">${rows.map((x, i) => `<div><i style="background:${colors[i % colors.length]}"></i>${esc(x[0])}<b>${x[1]}</b></div>`).join('') || '<small>No data</small>'}</div></div>` };
const adminDashboardBase = adminDashboard;
adminDashboard = async () => { await adminDashboardBase(); await renderAdminCharts() };
async function renderAdminCharts() {
    const host = M(); if (!host) return;
    const yr = +today().slice(0, 4), months = await Promise.all(Array.from({ length: 12 }, (_, i) => api('report', null, `&p=month&d=${yr}-${String(i + 1).padStart(2, '0')}-01`)));
    const rows = months.flat(), transactions = await api('adminpayments'), payments = transactions.filter(p => p.transaction_type == 'Payment' && p.status == 'Approved');
    const bookings = months.map(x => x.length), guestCounts = months.map(x => x.reduce((n, r) => n + (+r.guest_count || 0), 0)), revenue = Array(12).fill(0); payments.forEach(p => { const i = +(p.paid_at || '').slice(5, 7) - 1; if ((p.paid_at || '').slice(0, 4) == yr && i >= 0) revenue[i] += +p.amount });
    const status = ST.map(s => [s, rows.filter(r => r.status == s).length]), roomCounts = {}; rows.forEach(r => roomCounts[r.room_name] = (roomCounts[r.room_name] || 0) + 1);
    const methods = {}; payments.forEach(p => methods[p.payment_method] = (methods[p.payment_method] || 0) + +p.amount);
    host.insertAdjacentHTML('beforeend', `<h2 class="c12 chart-section-title">Performance charts · ${yr}</h2><div class="n pad c7 dashboard-chart"><h2>Monthly revenue received</h2>${bars(MON.map((m, i) => [m, revenue[i]]), money)}</div><div class="n pad c5 dashboard-chart"><h2>Booking status mix</h2>${donutChart(status)}</div><div class="n pad c6 dashboard-chart"><h2>Bookings per month</h2>${bars(MON.map((m, i) => [m, bookings[i]]))}</div><div class="n pad c6 dashboard-chart"><h2>Guests per month</h2>${bars(MON.map((m, i) => [m, guestCounts[i]]))}</div><div class="n pad c6 dashboard-chart"><h2>Most booked rooms / cottages</h2>${hb(Object.entries(roomCounts).sort((a, b) => b[1] - a[1]).slice(0, 6))}</div><div class="n pad c6 dashboard-chart"><h2>Revenue by payment method</h2>${donutChart(Object.entries(methods))}</div><div class="n pad c6 dashboard-chart"><h2>Payment review status</h2>${donutChart(['Approved', 'Pending', 'Rejected'].map(s => [s, transactions.filter(p => p.transaction_type == 'Payment' && p.status == s).length]))}</div><div class="n pad c6 dashboard-chart"><h2>Booking share by room</h2>${donutChart(Object.entries(roomCounts).sort((a,b)=>b[1]-a[1]).slice(0,6))}</div>`);
}
/* Give rooms/cottages usable category and pricing views while retaining the availability calendar. */
const roomsViewBase = V.rooms; V.rooms = async (arg) => { await roomsViewBase(arg); const head = document.querySelector('#main>.row'); if (!head || ROOM_ARCH) return; const tools = document.createElement('div'); tools.className = 'row c12'; const cat = arg?.category || 'All', sort = arg?.mode == 'pricing' ? 'price' : 'name'; tools.innerHTML = `<select id="roomfilter" onchange="filterRoomCards()"><option ${cat == 'All' ? 'selected' : ''}>All</option><option ${cat == 'Room' ? 'selected' : ''}>Room</option><option ${cat == 'Cottage' ? 'selected' : ''}>Cottage</option></select><select id="roomorder" onchange="filterRoomCards()"><option value="name" ${sort == 'name' ? 'selected' : ''}>Sort by name</option><option value="price" ${sort == 'price' ? 'selected' : ''}>Price: low to high</option><option value="availability" ${arg?.mode == 'availability' ? 'selected' : ''}>Availability</option></select><button class="btn sm ghost" onclick="document.querySelector(\'#cal\')?.scrollIntoView({behavior:\'smooth\'})">Availability calendar</button>`; head.after(tools); filterRoomCards() };
function filterRoomCards() { const cat = $('#roomfilter')?.value || 'All', sort = $('#roomorder')?.value || 'name'; let rows = ROOMS.filter(r => cat == 'All' || String(r.category).toLowerCase() == cat.toLowerCase()); rows.sort((a, b) => sort == 'price' ? +a.rate_per_night - +b.rate_per_night : sort == 'availability' ? +b.is_available - +a.is_available : String(a.room_name).localeCompare(String(b.room_name))); const box = $('#roomcards'); if (box) box.innerHTML = rows.map(r => `<div class="n card c4">${rimg(r)}<h3>${esc(r.room_name)}</h3><small>${esc(r.category)} · ${r.capacity} guests</small>${r.description ? `<p>${esc(r.description)}</p>` : ''}${r.amenities ? `<small>Amenities: ${esc(r.amenities)}</small>` : ''}<b>${money(r.rate_per_night)}/night</b><span class="badge ${r.is_available == 1 ? 'Confirmed' : 'Cancelled'}">${r.is_available == 1 ? 'Available' : 'Disabled'}</span><div class="row"><button class="btn sm" onclick="roomForm(${r.room_id})">Edit</button><button class="btn sm ghost" onclick="archiveRoom(${r.room_id},0)">Archive</button><button class="btn sm bad" onclick="deleteRoom(${r.room_id})">Delete</button></div></div>`).join('') || '<p class="mut">No rooms in this category.</p>' }
/* Inventory brings rooms, cottages, and rates together; the calendar has its own Availability page. */
V.rooms = async () => {
    ROOM_ARCH = 0; ROOMS = await api('rooms');
    M().innerHTML = `<section class="inventory-page c12"><header class="inventory-heading"><div><span class="dashboard-eyebrow">ACCOMMODATIONS</span><h2>Rooms & cottages</h2><p class="mut">Manage descriptions, rates, availability, and photo galleries in one place.</p></div><button class="btn sm ghost" onclick="roomForm(0)">+ Add accommodation</button></header><div class="inventory-toolbar"><div class="inventory-tabs"><button id="activeRoomsBtn" class="on" onclick="toggleRoomArchive(0)">Active inventory</button><button id="archivedRoomsBtn" onclick="toggleRoomArchive(1)">Archived</button></div><label class="inventory-filter">Type<select id="roomfilter" onchange="filterRoomCards()"><option value="All">All types</option><option value="Room">Rooms</option><option value="Cottage">Cottages</option><option value="Suite">Suites</option><option value="Event">Event spaces</option></select></label><label class="inventory-filter">Sort by<select id="roomorder" onchange="filterRoomCards()"><option value="name">Name</option><option value="price">Price: low to high</option><option value="price-desc">Price: high to low</option></select></label></div><div id="roomcards" class="g inventory-grid"></div></section>`;
    filterRoomCards();
};
function inventoryCards(rows) {
    const box = $('#roomcards'); if (!box) return;
    box.innerHTML = rows.map(r => `<article class="n card accommodation-card">${rimg(r)}<div class="accommodation-info"><div class="accommodation-tags"><span class="badge">${esc(r.category || 'Room')}</span><span class="badge ${r.is_available == 1 ? 'Confirmed' : 'Cancelled'}">${r.is_available == 1 ? 'Available' : 'Closed'}</span></div><h3>${esc(r.room_name)}</h3><p class="accommodation-meta">Up to ${r.capacity} guests</p>${r.description ? `<p class="accommodation-description">${esc(r.description)}</p>` : ''}${r.amenities ? `<p class="accommodation-amenities"><b>Amenities</b> · ${esc(r.amenities)}</p>` : ''}<div class="accommodation-footer"><div><b class="accommodation-price">${money(r.rate_per_night)}</b><small> / night</small></div><div class="accommodation-actions"><button class="btn sm ghost" onclick="roomDetails(${r.room_id})">Details</button><button class="btn sm ghost" onclick="roomForm(${r.room_id})">Edit</button>${ROOM_ARCH ? `<button class="btn sm ghost" onclick="archiveRoom(${r.room_id},0)">Restore</button>` : `<button class="btn sm ghost" onclick="archiveRoom(${r.room_id},1)">Archive</button>`}<button class="btn sm ghost" onclick="deleteRoom(${r.room_id})">Delete</button></div></div></div></article>`).join('') || `<p class="n pad c12 mut">${ROOM_ARCH ? 'No archived accommodations.' : 'No rooms or cottages match these filters.'}</p>`;
}
function filterRoomCards() {
    const cat = $('#roomfilter')?.value || 'All', sort = $('#roomorder')?.value || 'name';
    const rows = ROOMS.filter(r => cat == 'All' || String(r.category).toLowerCase() == cat.toLowerCase()).sort((a, b) => sort == 'price' ? +a.rate_per_night - +b.rate_per_night : sort == 'price-desc' ? +b.rate_per_night - +a.rate_per_night : String(a.room_name).localeCompare(String(b.room_name)));
    inventoryCards(rows);
}
function roomDetails(id) {
    const r = ROOMS.find(x => x.room_id == id); if (!r) return;
    modal(`<h3>${esc(r.room_name)}</h3>${rimg(r,'detail-gallery')}<div class="detail-summary"><span class="badge">${esc(r.category || 'Room')}</span><span>${r.capacity} guests</span><b>${money(r.rate_per_night)} / night</b><span class="badge ${r.is_available == 1 ? 'Confirmed' : 'Cancelled'}">${r.is_available == 1 ? 'Available to book' : 'Currently closed'}</span></div>${r.description ? `<div class="detail-copy"><h4>About this accommodation</h4><p>${esc(r.description)}</p></div>` : ''}${r.amenities ? `<div class="detail-copy"><h4>Amenities</h4><p>${esc(r.amenities)}</p></div>` : ''}`);
}
async function refreshRooms() { ROOMS = await api('rooms', null, '&arch=' + ROOM_ARCH); if ($('#roomcards')) filterRoomCards() }
async function toggleRoomArchive(v = 0) {
    const y = window.scrollY; ROOM_ARCH = v; ROOMS = await api('rooms', null, '&arch=' + v);
    $('#activeRoomsBtn')?.classList.toggle('on', !v); $('#archivedRoomsBtn')?.classList.toggle('on', !!v);
    const add = document.querySelector('.inventory-heading>.btn'); if (add) add.classList.toggle('hidden', !!v);
    filterRoomCards(); requestAnimationFrame(() => window.scrollTo(0, y));
}
async function archiveRoom(id, arch) { const y = window.scrollY; await T(async () => { await api('archiveroom', { id, arch }); toast(arch ? 'Accommodation archived' : 'Accommodation restored'); await refreshRooms(); requestAnimationFrame(() => window.scrollTo(0, y)) }) }
async function deleteRoom(id) { if (!confirm('Permanently delete this accommodation? Rooms with booking history can only be archived.')) return; const y = window.scrollY; await T(async () => { await api('delroom', { id }); toast('Accommodation deleted'); await refreshRooms(); requestAnimationFrame(() => window.scrollTo(0, y)) }) }
V.availability = async () => {
    ROOM_ARCH = 0; ROOMS = await api('rooms');
    M().innerHTML = `<section class="n pad c12 availability-page"><header class="inventory-heading"><div><span class="dashboard-eyebrow">ROOM PLANNING</span><h2>Availability calendar</h2><p class="mut">See confirmed stays against rooms available for booking.</p></div><div class="calnav"><button class="btn sm ghost" onclick="shiftCal(-1)" aria-label="Previous month">&lsaquo;</button><input type="month" id="cm" value="${today().slice(0,7)}" onchange="cal()"><button class="btn sm ghost" onclick="shiftCal(1)" aria-label="Next month">&rsaquo;</button></div></header><div class="availability-summary"><span><b>${ROOMS.filter(r=>r.is_available==1).length}</b> active rooms / cottages</span><span class="availability-legend"><i></i> Confirmed bookings</span></div><div id="cal"></div></section>`;
    await cal();
};
async function refreshAvailability() { if (!$('#cal')) return; ROOMS = await api('rooms'); await cal() }

/* Guest payment submissions stay pending until an admin checks the receipt. */
V.payments = async () => { const d = await api('payments'), due = d.bookings.reduce((a, r) => a + Math.max(0, +r.total - (+r.amount_paid || 0)), 0), paid = d.bookings.reduce((a, r) => a + (+r.amount_paid || 0), 0); M().innerHTML = `<div class="n stat c6"><div class="ico">${ic('card')}</div><div><small>Amount paid</small><div class="big">${money(paid)}</div></div></div><div class="n stat c6"><div class="ico">${ic('clock')}</div><div><small>Remaining balance</small><div class="big">${money(due)}</div></div></div><div class="n pad c12"><h2>Unpaid and partially paid bookings</h2><div class="tw">${d.bookings.filter(r => r.payment_status != 'Paid').map(r => `<div class="paymentrow"><b>#${r.reservation_id} · ${esc(r.room_name)}</b><span>${r.check_in_date} to ${r.check_out_date}</span><span>${money(r.amount_paid)} paid of ${money(r.total)} · ${r.payment_status}</span><div class="acts"><button class="btn sm ghost" onclick="paymentReceipt(${r.reservation_id})">Statement</button>${r.status === 'Checked-In' ? `<button class="btn sm" onclick="guestPaymentForm(${r.reservation_id},${r.total},${r.amount_paid})">Submit proof</button>` : '<small class="mut">Payment available at check-in</small>'}</div></div>`).join('') || '<p class="mut">All bookings are paid in full.</p>'}</div></div><div class="n pad c12"><h2>Payment history & proof status</h2><div class="tw">${d.history.length ? `<table class="payment-table"><thead><tr><th>Date</th><th>Booking</th><th>Room</th><th>Method</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody>${d.history.map(p => `<tr><td>${p.paid_at.slice(0, 16)}</td><td>#${p.reservation_id}</td><td>${esc(p.room_name)}</td><td>${esc(p.payment_method)}</td><td>${money(p.amount)}</td><td><span class="badge ${p.status}">${esc(p.status || 'Approved')}</span></td><td><button class="btn sm ghost" onclick="paymentReceipt(${p.reservation_id})">Statement</button></td></tr>`).join('')}</tbody></table>` : '<p class="mut">No payments or proof submissions yet.</p>'}</div></div>` };
function guestPaymentForm(id, total, paid) { const remaining = Math.max(0, +total - (+paid || 0)); modal(`<h3>Submit payment proof · Booking #${id}</h3><p>Remaining balance: <b>${money(remaining)}</b></p><label>Amount<input id="guestpayamount" type="number" min="0.01" max="${remaining}" step="0.01"></label><label>Payment method<select id="guestpaymethod"><option>GCash</option><option>Bank transfer</option><option>Cash</option><option>Other</option></select></label><label>Receipt / proof (JPEG, PNG, WebP; max 3 MB)<input id="guestpayfile" type="file" accept="image/jpeg,image/png,image/webp"></label><button class="btn" onclick="submitGuestPayment(${id})">Send for review</button>`) }
async function submitGuestPayment(id) { await T(async () => { const f = $('#guestpayfile').files[0]; if (!f) return toast('Choose a payment proof image first.', 1); if (f.size > 3e6) return toast('Image must be under 3 MB.', 1); const proof = await new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(reader.result); reader.onerror = reject; reader.readAsDataURL(f) }); await api('submitpayment', { reservation_id: id, amount: $('#guestpayamount').value, method: $('#guestpaymethod').value, proof }); document.querySelector('.modal')?.remove(); toast('Payment proof sent for admin review'); go('payments') }) }
const paymentsAdminBase = V.paymentsAdmin; V.paymentsAdmin = async arg => { window.ADMIN_PAYMENTS = await api('adminpayments'); return paymentsAdminBase(arg) };
const profileViewBeforeOtp=V.profile;V.profile=async()=>{await profileViewBeforeOtp();const box=document.querySelector('#main > .n.pad.c12');if(box)box.innerHTML='<h2>Change password</h2><p class="mut">For security, we will email a one-time code before changing your password.</p><div class="row"><label>Current password<input id="o1" type="password" autocomplete="current-password"></label><button class="btn" onclick="requestPasswordOtp()">Email me a code</button></div><div id="passwordOtpStep" class="hidden"><div class="row"><label>Email verification code<input id="passwordOtp" inputmode="numeric" autocomplete="one-time-code" maxlength="6"></label><label>New password (6+)<input id="newPassword" type="password" autocomplete="new-password"></label><label>Confirm new password<input id="confirmPassword" type="password" autocomplete="new-password"></label></div><button class="btn" onclick="savePw()">Verify code and change password</button></div>'};
async function requestPasswordOtp(){await T(async()=>{const r=await api('password',{old:$('#o1').value});$('#passwordOtpStep').classList.remove('hidden');toast('Password verification code sent to '+r.email)})}
savePw=async()=>{if($('#newPassword').value.length<6)return toast('New password must be at least 6 characters.',1);if($('#newPassword').value!==$('#confirmPassword').value)return toast('Passwords do not match.',1);await T(async()=>{await api('changepassword',{code:$('#passwordOtp').value,password:$('#newPassword').value});toast('Password changed successfully.');go('profile')})};
V.logout = () => logout();
boot();
